import argparse
import json
import numpy as np
import torch
from adaptation import load_pretrained, stack_params, batched_forward, make_adaptation_data, pole

#Linear-regression baselines for run_adaptation.py, fit on exactly the same n fine-tuning examples of each task:
#  OLS (minimum-norm least squares when n < d), ridge shrinking toward 0, and ridge shrinking toward the pretraining
#  pole v (an estimator that knows the task alignment but nothing else about the pretrained model).
#The data are regenerated by replaying make_adaptation_data with the run's seed. CUDA draws depend on the GPU model,
#so the replay is checked against the saved zero-context risks and step-0 training losses before anything is saved.
#Under x ~ N(0, I) the excess risk of a linear estimate is exactly |w_hat - w|^2.
parser = argparse.ArgumentParser()
parser.add_argument("--adaptation", type=str, required=True, help="adaptation_noise*.npz written by run_adaptation.py")
parser.add_argument("--lambdas", type=float, nargs="+", default=[0, 1e-3, 1e-2, 3e-2, 0.1, 0.3, 1, 3, 10, 30, 100],
                    help="ridge penalties; lambda = 0 is OLS (minimum-norm when n < d)")
parser.add_argument("--rtol", type=float, default=1e-3)
parser.add_argument("--out", type=str, default=None)
args = parser.parse_args()

device = 'cuda'
D = np.load(args.adaptation)
a = json.loads(str(D['args']))
model, margs = load_pretrained(a['pretrained'], device)
dim = margs['dim']
data_seed = margs['seed'] if a['data_seed'] is None else a['data_seed']
data = make_adaptation_data(dim, margs['seq_len'], a['deltas'], a['tasks_val'], a['tasks_test'], a['n_ctx'], a['n_query'],
                            max(a['ns']), np.sqrt(a['noise_var']), data_seed, device)
E = data['W'].shape[0]

#replay check: same tasks, same query points (R_zero), same FT examples (step-0 training loss at every n)
assert np.array_equal(data['member_delta'], D['member_delta']) and np.array_equal(data['member_split'], D['member_split'])
err_W = np.abs(data['W'].cpu().numpy() - D['W']).max()
with torch.no_grad():
    P0 = stack_params(model, E)
    zero = torch.zeros(data['Xq'].shape[:3], device=device)
    R_zero = ((batched_forward(P0, data['Xq'], zero)[..., 0] - data['Fq'][..., 0]) ** 2).mean(1).cpu().numpy()
    pred = batched_forward(P0, data['Xtr'], torch.zeros(data['Xtr'].shape[:3], device=device))[..., 0]
    sq = ((pred - data['Ytr'][..., 0]) ** 2).cpu().numpy()
del P0
L0 = np.stack([sq[:, :n].mean(1) for n in D['ns']])
err_zero = np.abs(R_zero / D['R_zero'] - 1).max()
err_train = np.abs(L0 / D['L_train'][:, 0, 0] - 1).max()
print("replay check: max |dW| {0:.1e}, max rel err R_zero {1:.1e}, step-0 train loss {2:.1e}".format(err_W, err_zero, err_train))
assert err_W < 1e-6 and err_zero < args.rtol and err_train < args.rtol, \
    "replayed data differ from the run's (run on the GPU model the adaptation job used)"

W = data['W'].double()
centers = {"zero": torch.zeros_like(W), "pole": pole(dim, device).double()[None, :].expand_as(W)}
R = {c: np.zeros((len(D['ns']), len(args.lambdas), E)) for c in centers}
eye = torch.eye(dim, device=device, dtype=torch.float64)
for i, n in enumerate(D['ns']):
    X, y = data['Xtr'][:, :n, 0].double(), data['Ytr'][:, :n, 0].double()
    for c, w0 in centers.items():
        r = y - torch.einsum('end,ed->en', X, w0)
        for j, lam in enumerate(args.lambdas):
            if lam == 0:
                w_hat = w0 + torch.einsum('edn,en->ed', torch.linalg.pinv(X), r)
            else:
                A = X.transpose(1, 2) @ X + lam * eye
                w_hat = w0 + torch.linalg.solve(A, torch.einsum('end,en->ed', X, r))
            R[c][i, j] = ((w_hat - W) ** 2).sum(1).cpu().numpy()

out = args.out or args.adaptation.replace("adaptation_", "baselines_")
np.savez(out, R_ridge=R["zero"], R_ridge_pole=R["pole"], lambdas=np.array(args.lambdas), ns=D['ns'],
         member_delta=D['member_delta'], member_split=D['member_split'], noise_var=a['noise_var'],
         replay_err=np.array([err_W, err_zero, err_train]))
test = D['member_split'] == "test"
print("median test OLS risk by n:", np.array2string(np.median(R["zero"][:, 0, test], axis=1), precision=3))
print("saved", out)
